import json
from pathlib import Path


def lesson(title, purpose, concepts, steps, exercise, deliverable):
    concept_html = "".join(f"<li><strong>{name}:</strong> {detail}</li>" for name, detail in concepts)
    step_html = "".join(f"<li>{step}</li>" for step in steps)
    return {
        "title": title,
        "content": (
            f"<h2>{title}</h2>"
            f"<p>{purpose}</p>"
            "<h3>Core ideas</h3>"
            f"<ul>{concept_html}</ul>"
            "<h3>Guided implementation</h3>"
            f"<ol>{step_html}</ol>"
            "<h3>Engineering notes</h3>"
            "<p>Keep the data contract, transformation pipeline, and runtime behavior explicit. Record assumptions beside the code, use deterministic seeds where the API supports them, and separate experiments from production integration. A model is useful only when its inputs, outputs, quality threshold, and failure behavior are understood by the team that operates it.</p>"
            "<p>Validate the result with data the model did not see during training. Log the model version and the important inputs needed to reproduce a prediction while avoiding secrets and personal data. Prefer a small baseline that is easy to explain before adding complexity.</p>"
            "<h3>Hands-on exercise</h3>"
            f"<p>{exercise}</p>"
            "<h4>Exercise checklist</h4>"
            "<ul><li>Create a repeatable project and sample data set.</li><li>Implement the pipeline described in this lesson.</li><li>Measure the result with an appropriate metric or acceptance test.</li><li>Write a short note explaining one limitation and one next improvement.</li></ul>"
            "<h3>Expected deliverable</h3>"
            f"<p>{deliverable}</p>"
        ),
    }


